-- ============================================================
-- 拦截器合并迁移 (commit 57bf9a349): 给 186 个 login/common→base 迁移接口
-- 打上 type=1 分组标签
--
-- 用途:
--   type 字段从「鉴权档位」改为「接口分组纯标签」,用于后续按组批量操作 through.
--   type=1 = "login/common→base 迁移组"(原 login 包 9 个 Action + 原 common 包 40 个 Action).
--
-- 前置依赖:
--   1. OperationServiceImpl.java:258-259 已修复 getType()→getThrough()
--      (否则 type=1 会被误读为 THROUGH_PASS_INT 短路放行,关闸关不掉)
--   2. dbs/operation_register_migrated_actions.sql 已执行,186 接口已登记
--
-- 幂等: UPDATE 天然幂等,重复执行无害
--
-- 后续关闸示例:
--   -- 按组批量收紧:把迁移组中所有 still through=1 的接口关闸
--   UPDATE communion.operation SET through = 0
--   WHERE type = 1 AND through = 1 AND status = 0;
--
--   -- 单接口关闸(同时清标签,避免与未来其他分组语义混淆)
--   UPDATE communion.operation SET through = 0, type = 0
--   WHERE operation = 'xxx';
-- ============================================================

